<?php
require_once '../config/database.php';require_once '../config/auth.php';$u=requireAuth();if($u['perfil']!=='ADMIN_GERAL')jsonResponse(false,'Acesso do administrador geral.',[],403);
$meses=[];for($i=11;$i>=0;$i--){$meses[]=date('Y-m',strtotime("first day of -$i month"));}$dados=[];foreach($meses as $m){$ini=$m.'-01 00:00:00';$fim=date('Y-m-t 23:59:59',strtotime($ini));$s=$conn->prepare("SELECT COALESCE(SUM(total),0) v FROM pedidos WHERE empresa_id=1 AND status IN('PAGO','PROCESSANDO','FINALIZADO') AND criado_em BETWEEN ? AND ?");$s->bind_param('ss',$ini,$fim);$s->execute();$c=(float)$s->get_result()->fetch_assoc()['v'];$s=$conn->prepare("SELECT COALESCE(SUM(valor_final),0) v FROM servicos WHERE empresa_id=2 AND status IN('FINALIZADO','ENTREGUE') AND COALESCE(finalizado_em,criado_em) BETWEEN ? AND ?");$s->bind_param('ss',$ini,$fim);$s->execute();$ma=(float)$s->get_result()->fetch_assoc()['v'];$s=$conn->prepare("SELECT COALESCE(SUM(valor),0) v FROM viagens WHERE empresa_id=3 AND status='FINALIZADA' AND COALESCE(data_finalizacao,data_saida) BETWEEN ? AND ?");$s->bind_param('ss',$ini,$fim);$s->execute();$t=(float)$s->get_result()->fetch_assoc()['v'];$dados[]=['mes'=>$m,'comercial'=>$c,'manutencoes'=>$ma,'transportes'=>$t,'grupo'=>$c+$ma+$t];}jsonResponse(true,'',['mensal'=>$dados]);
